export function normalizePatternKey(key) {
  if (!key) return "none";
  if (BG_PATTERNS[key]) return key;
  const legacyMap = {
    blossom: "blossom-trees",
  };
  return BG_PATTERNS[legacyMap[key]] ? legacyMap[key] : "none";
}
